const ENV_KEYS = [
  "SKILLS_SANDBOX_RUNTIME",
  "SKILLS_AGENT_SANDBOX_POOLS",
  "SKILLS_AGENT_SANDBOX_POOL",
  "SKILLS_AGENT_SANDBOX_NAMESPACE",
  "SKILLS_AGENT_SANDBOX_KUBECONFIG",
  "SKILLS_AGENT_SANDBOX_KUBECTL",
