/**
 * Declared providerSpecificData fields that contain credentials and must use the
 * same at-rest encryption as top-level connection tokens (#16836).
 *
 * Do not blanket-encrypt the JSON object: workspace/identity fields are queried
 * by SQLite and must remain readable. Unknown fields remain unchanged.
 *
 * This is the ONE list for every consumer: encryptConnectionFields /
 * decryptConnectionFields (src/lib/db/encryption.ts), the lazy connection views,
 * the first-use sweep of legacy plaintext rows (./migrations.ts), the provider API
 * response sanitizer (src/lib/providers/requestDefaults.ts — strips these fields,
 * masks `extraApiKeys` like `apiKey`) and the compliance audit summary
 * (src/lib/compliance/providerAudit.ts). A field added here is covered on every side;
 * tests/unit/provider-specific-data-secrets-drift.test.ts iterates the list.
 */
export const PROVIDER_SPECIFIC_SECRET_FIELDS = [
  "consoleApiKey",
  "alibabaConsoleCookie",
  "alibabaConsoleSecToken",
  "xiaomiMimoConsoleCookie",
  // Console-only quota cookies/tokens live alongside the inference API key;
  // none are SQLite identity fields. Keeping them plaintext on disk exposes
  // the cloud-console account to anyone who can read the database.
  "qwenCloudCookie",
  "qwenCloudSecToken",
  "volcConsoleCookie",
  "volcCsrfToken",
  // Ollama Cloud's optional quota-scraping session credentials are the same
  // class of browser cookie as the Qwen/Volcengine console credentials above.
  // Only encrypt credential fields; workspace/identity JSON stays queryable.
  "ollamaUsageCookie",
  "ollamaCloudUsageCookie",
  "ollamaCloudCookie",
  "usageCookie",
  // Some connectors store a second credential or session token inside the
  // metadata object. These fields are already redacted from dashboard/audit
  // responses, but without declaring them here their SQLite values leak in
  // plaintext. Keep non-secret IDs (workspaceId/chatgptUserId) queryable.
  "accessToken",
  "refreshToken",
  "idToken",
  "apiKey",
  "secretAccessKey",
  "awsSecretAccessKey",
  "sessionToken",
  "awsSessionToken",
  "openCodeGoAuthCookie",
  "opencodeGoAuthCookie",
  "authCookie",
  // The key-rotation pool: a LIST of full upstream API keys. Every entry is
  // enveloped (see mapProviderSpecificDataSecrets); the dashboard shows and
  // edits the list, so the API returns it masked exactly like `apiKey`.
  "extraApiKeys",
  // The Zed Hosted billing portal link embeds its Orb portal token, so the whole
  // value is a credential even though it looks like a URL.
  "billingPortalUrl",
  // Short-lived provider sub-tokens that refresh / mint flows write back into
  // the metadata object (open-sse/executors/ghe-copilot.ts,
  // open-sse/services/tokenRefresh/providers/museCode.ts + kiro.ts,
  // open-sse/executors/lmarena.ts).
  "copilotToken",
  "dcaToken",
  "clientSecret",
  "recaptchaV3Token",
  // Web-session providers keep the browser session under these keys
  // (src/shared/providers/webSessionCredentials.ts → storageKeys). Identity and
  // display fields of those providers (uuid, uid, sid, deviceId, userId, email,
  // projectId, space ids, …) are not credentials and stay queryable.
  "cookie",
  "cookies",
  "storageState",
  "origins",
  "token",
  "token_v2",
  "userToken",
  "access_token",
  "refresh_token",
  "jwt",
  "sso",
  "sso-rw",
  "session",
  "session-token",
  "sessionCookie",
  "sessionKey",
  "sessionid",
  "__Secure-next-auth.session-token",
  "__Secure-authjs.session-token",
  "__Secure-better-auth.session_token",
  "__Secure-1PSID",
  "__Secure-1PSIDTS",
  "__client",
  "__session",
  "__vercel_session",
  "app-config-uuid",
  "hy_token",
  "hf-chat",
  "p-b",
  "kimi-auth",
  "duckai",
  "chatglm_session",
  "manus_session",
  "ecto_1_sess",
  "abra_sess",
  "convex-session-id",
  "convexSessionId",
  "nt_session",
  "si_ses_id",
  "ttwid",
  "arena-auth-prod-v1",
  "arena-auth-prod-v1.0",
  "arena-auth-prod-v1.1",
  "maxaiAccessToken",
  "ucCookies",
  "ucClientCookie",
  "clientCookie",
  "wordpress_logged_in",
] as const;

/**
 * Not credentials at rest, but never echoed to a client or written to an audit record:
 * the transient ChatGPT Web (Codex) handles, the system-managed Codex fingerprint seed
 * (mirrors sub2api stripping `codex_fingerprint_seed`) and the runtime-only Codex
 * identity carriers (in-memory per request, never persisted). The server-side
 * partial-update merge keeps them alive without the client round-tripping them.
 */
export const PROVIDER_SPECIFIC_RESPONSE_ONLY_FIELDS = [
  "runtimeKey",
  "validationId",
  "codexFingerprintSeed",
  "codexClientIdentity",
  "codexOriginalIdentityHeaders",
  "codexTurnStateEcho",
] as const;

export type ProviderSpecificSecretField = (typeof PROVIDER_SPECIFIC_SECRET_FIELDS)[number];

/** Declared secret fields plus any dynamically-named secret key present in `data`. */
export function providerSpecificSecretKeysIn(data: Record<string, unknown>): string[] {
  const keys: string[] = [...PROVIDER_SPECIFIC_SECRET_FIELDS];
  for (const key of Object.keys(data)) {
    if (!keys.includes(key) && isWordPressLoggedInKey(key)) keys.push(key);
  }
  return keys;
}

type SecretTransform = (
  secret: string,
  field: ProviderSpecificSecretField
) => string | null | undefined;

/**
 * Apply `transform` to one declared value: a string, or each string entry of a list
 * (the `extraApiKeys` pool). Returns the input itself when nothing changed, so callers
 * can skip the copy. A list entry that transforms to null/undefined is DROPPED — an
 * undecryptable token must never be forwarded upstream as if it were a key — while
 * non-string / empty entries and non-string, non-list values pass through untouched.
 */
function mapSecretValue(
  value: unknown,
  field: ProviderSpecificSecretField,
  transform: SecretTransform
): unknown {
  if (typeof value === "string") return value ? transform(value, field) : value;
  if (!Array.isArray(value)) return value;
  let changed = false;
  const next: unknown[] = [];
  for (const entry of value) {
    if (typeof entry !== "string" || !entry) {
      next.push(entry);
      continue;
    }
    const mapped = transform(entry, field);
    if (mapped !== entry) changed = true;
    if (mapped === null || mapped === undefined) continue;
    next.push(mapped);
  }
  return changed ? next : value;
}

/** Return a fresh object only if a recognized secret field actually changes. */
export function mapProviderSpecificDataSecrets(data: unknown, transform: SecretTransform): unknown {
  if (!data || typeof data !== "object" || Array.isArray(data)) return data;
  const original = data as Record<string, unknown>;
  let updated: Record<string, unknown> | null = null;
  for (const field of providerSpecificSecretKeysIn(original)) {
    const secret = [REDACTED]];
    const value = mapSecretValue(secret, field as ProviderSpecificSecretField, transform);
    if (value !== secret) {
      updated ??= { ...original };
      updated[field] = value;
    }
  }
  return updated ?? data;
}

import { isDashboardSessionAuthenticated } from "@/shared/utils/apiAuth.ts";
import { recordApiKeyAuthTouch } from "@/lib/compliance/index";
import { classifyIpScope, getClientIpFromRequest } from "@/lib/ipUtils";
import { isFeatureFlagEnabled, isRequireApiKeyEnabled } from "@/shared/utils/featureFlags";
import { extractApiKeyCandidates } from "@/sse/services/clientApiKeyResolver.ts";
import { isEntraSsoEnabled } from "../entra/config";
import { evaluateSsoAuth, looksLikeEntraJwt } from "../entra/evaluate";
import type { AuthOutcome, PolicyContext, RoutePolicy } from "../context";
import { allow, reject } from "../context";
import { isViaProxyRequest, requestPeerAddress } from "../peerContext";

const HANDSHAKE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);

function isWsHandshake(ctx: PolicyContext): boolean {
  if (ctx.classification.normalizedPath !== "/api/v1/ws") return false;
  if (!HANDSHAKE_METHODS.has(ctx.request.method.toUpperCase())) return false;

  try {
    return new URL(ctx.request.url, "http://localhost").searchParams.get("handshake") === "1";
  } catch {
    return false;
  }
}

/** `/a2a` accepts header credentials only (#19832): never a URL-borne token. */
function isA2aPath(normalizedPath: string): boolean {
  return normalizedPath === "/a2a" || normalizedPath.startsWith("/a2a/");
}

function maskKeyId(apiKey: string): string {
  const tail = apiKey.slice(-4);
  return `key_${tail}`;
}

function redactCredentials(
  value: string | null,
  credentials: Array<string | null | undefined>
): string | null {
  if (!value) return null;
  let sanitized = value;
  for (const credential of credentials) {
    if (credential) sanitized = sanitized.split(credential).join("[redacted]");
  }
  return sanitized;
}

function getAuthTouchClientIp(ctx: PolicyContext): string {
  const peerAddress = requestPeerAddress(ctx);
  const peerScope = classifyIpScope(peerAddress);
  const trustedProxyHop =
    isViaProxyRequest(ctx) && (peerScope === "loopback" || peerScope === "private");

  return getClientIpFromRequest({
    headers: ctx.request.headers,
    // A token-validated proxy stamp plus a local/private socket peer is the
    // app's trusted-proxy boundary. Withhold that hop so ipUtils resolves the
    // forwarded client. Public/direct peers remain authoritative even if they
    // spoof forwarding headers.
    ip: trustedProxyHop ? undefined : (peerAddress ?? undefined),
  });
}

/**
 * Opt-in (default off): record the caller's IP and user-agent on auth-touch rows.
 * Off, the row still records which key was used, when, and on which path.
 */
export const API_KEY_AUDIT_CLIENT_DETAILS_FLAG = "API_KEY_AUDIT_CLIENT_DETAILS_ENABLED";

/**
 * Best-effort audit of a successful GET/HEAD API-key authentication (metadata and
 * discovery reads that never reach the inference call log). Honours noLog keys and
 * the env key, and redacts every presented credential from the recorded path/UA.
 * Client IP and user-agent are recorded only with API_KEY_AUDIT_CLIENT_DETAILS_FLAG on.
 */
async function recordClientApiAuthTouch(
  ctx: PolicyContext,
  credential: string,
  credentials: string[]
): Promise<void> {
  const method = ctx.request.method.toUpperCase();
  if (method !== "GET" && method !== "HEAD") return;
  // Best effort end to end: the key already validated, so a failure in the metadata
  // lookup, IP resolution or redaction must never change the auth outcome.
  try {
    const { getApiKeyMetadata } = await import("../../../lib/db/apiKeys");
    const metadata = await getApiKeyMetadata(credential);
    if (!metadata || metadata.id === "env-key" || metadata.noLog === true) return;
    const withClientDetails = isFeatureFlagEnabled(API_KEY_AUDIT_CLIENT_DETAILS_FLAG);
    recordApiKeyAuthTouch({
      apiKeyId: metadata.id,
      method,
      normalizedPath: redactCredentials(ctx.classification.normalizedPath, credentials) || "/",
      ipAddress: withClientDetails ? getAuthTouchClientIp(ctx) : null,
      userAgent: withClientDetails
        ? redactCredentials(ctx.request.headers.get("user-agent"), [
            ...credentials,
            metadata.keyHash,
          ])
        : null,
      requestId: ctx.requestId,
    });
  } catch {
    // Observability only; never block or reject an authenticated request.
  }
}

export const clientApiPolicy: RoutePolicy = {
  routeClass: "CLIENT_API",
  async evaluate(ctx: PolicyContext): Promise<AuthOutcome> {
    // Every credential the client presented, in precedence order (Bearer,
    // x-api-key, x-goog-api-key #7034, path-scoped `/vscode/<key>/…` token).
    // A non-"Bearer <token>" Authorization header (an empty "Bearer ", or a
    // client's own non-OmniRoute token — VS Code Copilot sends one even when the
    // OmniRoute key lives in the URL path of a /vscode tokenized endpoint) must
    // NOT short-circuit auth, and neither may an unrelated Bearer sent ALONGSIDE
    // a valid x-api-key (Claude Code with a claude.ai session or
    // ANTHROPIC_AUTH_TOKEN): the request is accepted when ANY credential validates.
    const allowUrl = !isA2aPath(ctx.classification.normalizedPath);
    const credentials = extractApiKeyCandidates(ctx.request as Request, { allowUrl });
    if (credentials.length === 0) {
      // The WS descriptor handshake is a metadata read; the route handler
      // performs the actual wsAuth/dashboard/API-key decision and returns the
      // protocol details the browser needs before opening the socket.
      if (isWsHandshake(ctx)) {
        return allow({ kind: "anonymous", id: "ws-handshake" });
      }

      if (await isDashboardSessionAuthenticated(ctx.request)) {
        return allow({ kind: "dashboard_session", id: "dashboard" });
      }

      if (!isRequireApiKeyEnabled()) {
        return allow({ kind: "anonymous", id: "local" });
      }

      return reject(401, "AUTH_002", "Authentication required");
    }

    // Runs before validateApiKey, but only while SSO is actually configured —
    // otherwise a client's own unrelated JWT would stop degrading to anonymous
    // under REQUIRE_API_KEY=false. Once SSO does claim a bearer, its outcome is
    // FINAL: falling through would let that same branch turn an Entra outage
    // into open access. The highest-precedence credential is the one SSO
    // inspects (Claude Code's apiKeyHelper sends the JWT as both Bearer and
    // x-api-key, so it is always first).
    const primary = credentials[0];
    if (looksLikeEntraJwt(primary) && (await isEntraSsoEnabled())) {
      const verdict = await evaluateSsoAuth(primary);
      if (!verdict.ok) {
        const failure = verdict as { status: number; code: string; message: string };
        return reject(failure.status, failure.code, failure.message);
      }
      return allow({
        kind: "sso_user",
        id: verdict.oid,
        label: verdict.upn || undefined,
      });
    }

    const { validateApiKey } = await import("../../../lib/db/apiKeys");
    for (const credential of credentials) {
      // The subject is the credential that actually validated, so identity and
      // usage never bind to a stale Bearer sent next to a valid x-api-key.
      if (await validateApiKey(credential)) {
        await recordClientApiAuthTouch(ctx, credential, credentials);
        return allow({ kind: "client_api_key", id: maskKeyId(credential) });
      }
    }

    // Issue #2257: when REQUIRE_API_KEY is off, a stale CLI config (Codex
    // Desktop auto-config, Hermes, etc.) carrying an invalid Bearer
    // shouldn't 401 the whole request — REQUIRE_API_KEY=false means
    // "anonymous traffic is allowed", so an invalid key should degrade to
    // anonymous instead of rejecting. We log a warning so the bad key is
    // still observable in the request log.
    if (!isRequireApiKeyEnabled()) {
      console.warn(
        `[clientApiPolicy] invalid bearer presented to ${ctx.classification.normalizedPath} ` +
          `but REQUIRE_API_KEY=false — falling through to anonymous (key_id=${maskKeyId(credentials[0])})`
      );
      return allow({ kind: "anonymous", id: "local" });
    }
    return reject(401, "AUTH_002", "Invalid API key");
  },
};

